import assert from 'node:assert/strict';
import { test } from 'node:test';
import { MAX_LENGTH, findLongLines, isChecked } from './line-length.mjs';

const long = (n) => 'x'.repeat(n);

test('the limit is 150 characters: 150 passes, 151 fails', () => {
  assert.equal(MAX_LENGTH, 150);
  assert.deepEqual(findLongLines('Program.cs', long(150)), []);
  assert.deepEqual(findLongLines('Program.cs', long(151)), [{ line: 1, length: 151 }]);
});

test('characters are counted as code points, not bytes or UTF-16 units', () => {
  assert.deepEqual(findLongLines('Program.cs', 'é'.repeat(150)), []);
  assert.deepEqual(findLongLines('Program.cs', '😀'.repeat(150)), []);
  assert.deepEqual(findLongLines('Program.cs', '😀'.repeat(151)), [{ line: 1, length: 151 }]);
});

test('every line of a C# file counts, the line numbers start at 1 and CRLF is not counted', () => {
  assert.deepEqual(findLongLines('A.cs', `ok\r\n${long(151)}\r\nok\n${long(160)}`), [{ line: 2, length: 151 }, { line: 4, length: 160 }]);
});

test('Markdown prose counts, but fenced code, table rows and bare URLs do not', () => {
  const text = [long(151), '```', long(200), '```', `| ${long(200)} |`, `See https://example.com/${long(200)}`, 'ok'].join('\n');
  assert.deepEqual(findLongLines('README.md', text), [{ line: 1, length: 151 }]);
});

test('a Markdown line with a URL and long prose around it still counts', () => {
  const text = `${long(160)} https://example.com/x`;
  assert.deepEqual(findLongLines('README.md', text), [{ line: 1, length: text.length }]);
});

test('a tilde fence and an indented fence open code too, and a fence closes only with its own kind', () => {
  const text = ['~~~', long(200), '```', long(200), '~~~', long(151)].join('\n');
  assert.deepEqual(findLongLines('a.md', text), [{ line: 6, length: 151 }]);
});

test('only C# and Markdown files are checked, and generated ones are not', () => {
  assert.equal(isChecked('src/A/Program.cs'), true);
  assert.equal(isChecked('docs/roadmap.md'), true);
  assert.equal(isChecked('Frappe.slnx'), false);
  assert.equal(isChecked('eng/just/test.just'), false);
  for (const file of ['src/A/Model.g.cs', 'src/A/Model.generated.cs', 'src/A/Migrations/20260101000000_Init.Designer.cs',
    'src/A/Migrations/AppDbContextModelSnapshot.cs', 'src/A/obj/Debug/Info.cs', 'src/A/bin/Release/Info.cs', 'CHANGELOG.md', 'node_modules/a/README.md']) {
    assert.equal(isChecked(file), false, file);
  }
});

test('a C# file marked auto-generated is skipped', () => {
  assert.deepEqual(findLongLines('Api.cs', `// <auto-generated />\n${long(300)}`), []);
});

test('Markdown YAML front matter is metadata and does not count; prose after it does', () => {
  const long = 'x'.repeat(151);
  const text = ['---', `description: ${long}`, '---', long].join('\n');
  assert.deepEqual(findLongLines('a.md', text), [{ line: 4, length: 151 }]);
});

test('a fence line with an info string inside a fence does not close it', () => {
  const long = 'x'.repeat(151);
  const text = ['````md', '```sql', long, '````', long].join('\n');
  assert.deepEqual(findLongLines('a.md', text), [{ line: 5, length: 151 }]);
});
